<section class="hero-card p-4 p-md-5"><div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-4"><div><span class="badge text-bg-success-subtle mb-2">Finanzas</span><h1 class="h2 fw-bold mb-1">Movimientos</h1><p class="text-secondary mb-0">Consulta y administra tus ingresos y gastos.</p></div><a class="btn btn-success" href="/movimientos/nuevo">Registrar movimiento</a></div>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= htmlspecialchars($success, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<?php if ($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach ($errors as $message): ?><li><?= htmlspecialchars($message, ENT_QUOTES, 'UTF-8') ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="row g-3 align-items-end mb-4" method="get" action="/movimientos"><div class="col-sm-6 col-lg-2"><label class="form-label" for="desde">Desde</label><input class="form-control" type="date" id="desde" name="desde" value="<?= htmlspecialchars($filters['desde'], ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-sm-6 col-lg-2"><label class="form-label" for="hasta">Hasta</label><input class="form-control" type="date" id="hasta" name="hasta" value="<?= htmlspecialchars($filters['hasta'], ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-sm-6 col-lg-3"><label class="form-label" for="categoria_id">Categoría</label><select class="form-select" id="categoria_id" name="categoria_id"><option value="">Todas</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (string) $filters['categoria_id'] === (string) $category['id'] ? 'selected' : '' ?>><?= htmlspecialchars($category['nombre'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-sm-6 col-lg-2"><label class="form-label" for="tipo">Tipo</label><select class="form-select" id="tipo" name="tipo"><option value="">Todos</option><option value="ingreso" <?= $filters['tipo'] === 'ingreso' ? 'selected' : '' ?>>Ingreso</option><option value="gasto" <?= $filters['tipo'] === 'gasto' ? 'selected' : '' ?>>Gasto</option></select></div><div class="col-lg-3 d-flex gap-2"><button class="btn btn-outline-success" type="submit">Filtrar</button><a class="btn btn-outline-secondary" href="/movimientos">Limpiar</a></div></form>
<?php if (!$movements): ?><div class="text-center py-5"><h2 class="h5">No hay movimientos</h2><p class="text-secondary">Registra un movimiento o ajusta los filtros.</p></div><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Tipo</th><th>Categoría</th><th>Descripción</th><th class="text-end">Valor</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach ($movements as $item): ?><tr><td><?= htmlspecialchars(date('d/m/Y', strtotime($item['fecha'])), ENT_QUOTES, 'UTF-8') ?></td><td><span class="badge <?= $item['tipo'] === 'ingreso' ? 'text-bg-success' : 'text-bg-warning' ?>"><?= $item['tipo'] === 'ingreso' ? 'Ingreso' : 'Gasto' ?></span></td><td><?= htmlspecialchars($item['categoria'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($item['descripcion'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td><td class="text-end fw-semibold <?= $item['tipo'] === 'ingreso' ? 'text-success' : 'text-danger' ?>"><?= $item['tipo'] === 'gasto' ? '−' : '+' ?>$<?= number_format((float) $item['monto'], 2, ',', '.') ?></td><td><div class="d-flex justify-content-end gap-2"><a class="btn btn-sm btn-outline-secondary" href="/movimientos/editar?id=<?= (int) $item['id'] ?>">Editar</a><form method="post" action="/movimientos/eliminar" onsubmit="return confirm('¿Eliminar este movimiento?')"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Eliminar</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
